insert into public.questao_figuras (questao_id, ordem, imagem, descricao) values
('2024-D1-Q077', 1, 'imagens/2024/D1/q077_fig1.webp', 'Três capas da revista “TRAVEL IN BRAZIL”, lado a lado. Na primeira, foto em preto e branco de uma mulher sorridente com turbante de flores, colares e muitas pulseiras (estilo Carmen Miranda), sobre fundo vermelho com figuras desenhadas de dançarinas de carnaval. Na segunda, ilustração de um gaúcho de chapéu e poncho branco montado a cavalo, sob céu azul. Na terceira, ilustração estilizada de três figuras em um campo — dois homens de costas com roupas típicas de vaqueiro/gaúcho, um deles de chapéu, e uma mulher de blusa vermelha de bolinhas e saia azul estampada. O título “TRAVEL IN BRAZIL” aparece em cada capa.'),
('2025-D1-Q049', 1, 'imagens/2025/D1/q049_fig1.webp', 'Pintura a óleo de uma praça em Veneza (a Piazzetta), com um longo edifício renascentista de arcadas e estátuas no alto à direita e uma coluna encimada por uma estátua ao fundo. Em primeiro plano, à esquerda, dois homens em trajes orientais (um de barrete vermelho e barba branca; outro de turbante, túnica branca e manto azul); ao centro e ao fundo, grupos de pessoas em trajes europeus do século XVIII conversam; à direita, homens sentados junto a uma banca com livros e caixotes; cães circulam pela praça.');
